from qiskit import QuantumRegister, QuantumCircuit
from math import pi

def qft_6():
    """QFT on 6 qubits"""
    qr = QuantumRegister(6, 'q')
    qc = QuantumCircuit(qr)
    for i in range(5, -1, -1):
        qc.h(qr[i])
        for j in range(i):
            qc.cp(pi/2**(i-j), qr[j], qr[i])

    for j in range(3): 
        qc.swap(qr[j], qr[5-j])

    return qc

