def QCL_circuit():
    n_qubits = 3
    depth = 2
    weights = [
            [[(9 * d + 3 * i + k + 1) * math.pi / 19 for k in range(3)] for i in range(n_qubits)]
            for d in range(depth)
        ]
    qr = QuantumRegister(n_qubits)
    qc = QuantumCircuit(qr)
    for d in range(depth):
        for i in range(n_qubits - 1):
            qc.cx(qr[i], qr[i + 1])
        qc.cx(qr[n_qubits - 1], qr[0])
        for i in range(n_qubits):
            qc.rx(weights[d][i][0], qr[i])
            qc.rz(weights[d][i][1], qr[i])
            qc.rx(weights[d][i][2], qr[i])
    return qc

