    edges = ((0, 1), (1, 2), (2, 3), (3, 0), (0, 2))
    gamma = (0.6, 0.3)
    beta = (0.4, 0.2)
    for qubit in range(4):
        qc.h(qubit)
    for layer in range(2):
        for control, target in edges:
            qc.cx(control, target)
            qc.rz(2 * gamma[layer], target)
            qc.cx(control, target)
        for qubit in range(4):
            qc.rx(2 * beta[layer], qubit)
    for qubit in range(4):
        qc.measure(qubit, qubit)
    return qc

