    def inverse_qft(qubits):
        n = len(qubits)
        for i in range(n // 2):
            qc.swap(qubits[i], qubits[n - 1 - i])
        for i in range(n):
            for j in range(i):
                qc.cp(-pi / (2 ** (i - j)), qubits[j], qubits[i])
            qc.h(qubits[i])

    for qubit in (0, 1, 2, 3, 4):
        qc.h(qubit)
    for control in range(3):
        scale = 2 ** control
        qc.cp(-pi / 4 * scale, control, 3)
        qc.cp(-pi / 2 * scale, control, 4)
    inverse_qft([0, 1, 2])
    for qubit in range(3):
        qc.measure(qubit, qubit)
    return qc
